defmodule JoobQ.EnqueueManyTest do
  use ExUnit.Case, async: true

  defp stored(batch), do: {:ok, %{"jobs" => Enum.map(batch, &%{"jid" => &1})}}

  test "post_batches answers every stored job in order" do
    assert JoobQ.post_batches([["a", "b"], ["c"]], &stored/1) ==
             {:ok, [%{"jid" => "a"}, %{"jid" => "b"}, %{"jid" => "c"}]}

    assert JoobQ.post_batches([], &stored/1) == {:ok, []}
  end

  test "a failed batch answers its error with the jobs the batches before it stored" do
    refusal = %JoobQ.Error{reason: :unavailable, status: 503, details: ["busy"]}
    post = fn batch -> if batch == ["c"], do: {:error, refusal}, else: stored(batch) end

    assert {:error, %JoobQ.Error{reason: :unavailable, details: details}} =
             JoobQ.post_batches([["a"], ["b"], ["c"], ["d"]], post)

    assert details == %{stored: [%{"jid" => "a"}, %{"jid" => "b"}], gateway: ["busy"]}
  end

  test "a first batch that fails answers the same shape, with nothing stored" do
    refusal = %JoobQ.Error{reason: :invalid, status: 422, details: ["x"]}

    assert JoobQ.post_batches([["a"]], fn _ -> {:error, refusal} end) ==
             {:error, %{refusal | details: %{stored: [], gateway: ["x"]}}}
  end
end
